// src/pages/Login.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Login.css';

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      alert('Please fill in all fields');
      return;
    }

    try {
      const response = await fetch('https://medivault-backend-ndak.onrender.com/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (!response.ok) {
        alert(data.message || 'Login failed');
        return;
      }

      const role = data.user.role;

      if (role === 'doctor') navigate('/dashboard/doctor');
      else if (role === 'patient') navigate('/dashboard/patient');
      else if (role === 'hospital') navigate('/dashboard/hospital');
      else navigate('/');

    } catch (error) {
      console.error('Login error:', error);
      alert('An error occurred. Please try again later.');
    }
  };

  return (
    <div className="container">
      {/* Left: Login Section */}
      <div className="login-section">
        <div className="login-card">
          <h2>Login to MediVault</h2>
          <form onSubmit={handleLogin}>
            <input
              type="email"
              placeholder="Email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button type="submit" className="login-btn">Login</button>
            <div className="links">
              <a href="#">Forgot Password?</a><br />
              Don’t have an account? <a href="/register">Register here</a>
            </div>
          </form>
        </div>
      </div>

      {/* Right: Welcome Section */}
      <div className="welcome-section">
        <div className="welcome-content">
          <h1>Welcome back to <span>MediVault</span></h1>
          <p>Your health, organized and always accessible.</p>
        </div>
        <div className="blob"></div>
        <div className="blob"></div>
        <div className="blob"></div>
      </div>
    </div>
  );
};

export default Login;
